// The inspector's icons: MBIcons carries MarchingBlocks' own icons as PNGs (generated by
// DEV_TOOLS/generer_icones_greffons.gd). A PNG that does not decode would leave an empty button, and no
// compiler would say so: each one is decoded here, through the Image Conversion module the package declares.

using System.Collections.Generic;
using System.Reflection;
using NUnit.Framework;
using UnityEngine;
using MarchingBlocks.Paint.EditorTools;

public sealed class PanelTests
{
    [Test]
    public void EveryIconDecodes()
    {
        var type = typeof(MarchingBlocksWorldEditor).Assembly.GetType("MarchingBlocks.Paint.EditorTools.MBIcons");
        Assert.IsNotNull(type, "MBIcons is missing from the editor assembly");
        var png = (Dictionary<string, string>)type.GetField("Png", BindingFlags.Static | BindingFlags.NonPublic).GetValue(null);
        Assert.GreaterOrEqual(png.Count, 30, "fewer icons than the inspector uses");
        var get = type.GetMethod("Get", BindingFlags.Static | BindingFlags.Public);
        foreach (var name in png.Keys)
        {
            var t = (Texture2D)get.Invoke(null, new object[] { name });
            Assert.IsNotNull(t, name);
            Assert.AreEqual(40, t.width, name + ": not decoded (a 2x2 placeholder stays when LoadImage fails)");
            Assert.AreEqual(40, t.height, name);
        }
    }
}
